dev-python-clamp.control:
def clamp(value, lower, upper):
    if lower > upper: return value
    return max(lower,min(value,upper))

dev-python-parking.control:
def parking(minutes):
    if minutes<=0: return 0
    return 3+((minutes-1)//60)*2

test-python-delivery.control:
def delivery_cost(weight,zone,priority):
    if zone<0 or zone>3: return -1
    if weight<=0: return 0
    return 5+2*zone+2*min(weight,10)+3*max(weight-10,0)+(7 if priority else 0)

test-python-overlap.control:
def overlap_length(start_a,end_a,start_b,end_b):
    if start_a>end_a or start_b>end_b: return 0
    return max(0,min(end_a,end_b)-max(start_a,start_b))

test-python-gcd.control:
def lattice_steps(a,b):
    a=abs(a)
    b=abs(b)
    while b:
        a,b=b,a%b
    return a

